// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 calls, uint256 seed) public {
        uint256 numCalls = bound(calls, 1, 10);
        uint256 totalTickets = 0;

        for (uint256 i = 0; i < numCalls; i++) {
            address player = address(uint160(uint256(keccak256(abi.encode(seed, i)))));
            vm.deal(player, 20 ether);
            vm.prank(player);
            (bool success, ) = address(c).call{value: 10 wei}(abi.encodeWithSignature("play()"));
            if (success) {
                totalTickets += 10 wei;
            }
        }

        assertTrue(c.pot() <= totalTickets);
    }
}
